 * Closure as the SPEC states it: encoding the operation's result tree must
 * re-parse to that same tree. `closure.test.ts` compares the RETURNED doc,
 * which `finalize` already produced by re-parsing — so it is true by
 * construction and blind to this. The real question is whether the op's own
 * intended tree survives its encoding, and the only visible proxy from outside
 * is whether a SECOND application of the same encoding is stable.
 *
 * Detect it differently: run the op, then check that re-parsing the emitted
 * TEXT yields a tree in which the subject sits where the op's anchor says it
 * does. A silent re-attachment moves the subject's depth.
 */
describe('measure', () => {
  it('how often does an op emit an encoding that re-parses differently', () => {
    const tally: Record<string, Record<string, number>> = {};
    const bump = (op: string, k: string) => { tally[op] ??= {}; tally[op]![k] = (tally[op]![k] ?? 0) + 1; };
