            const target = all[n % all.length]!;
            const before = [...walkNodes(doc)].length;
            const res = op(doc, target.id);
            if (!res.ok) return true;
            // Node COUNT is preserved by all four operations. A silent
            // re-attachment does not change the count, so compare depth of the
            // whole tree instead: re-encode and re-parse the RESULT and check
            // it is a fixpoint (it is, by construction) -- so instead compare
            // the result's node count and total depth against the input.
            const after = [...walkNodes(res.value.doc)].length;
            const key = `${gen[0]}`;
            if (after !== before) { bump(`${name}/${key}`, 'COUNT-CHANGED'); return true; }
            bump(`${name}/${key}`, 'ok');
